/* ================= 全局容器 ================= */
.mz-ig-story-vibe-2x2 {
  width: 100%; height: 100%; position: relative; overflow: hidden;
  aspect-ratio: 1 / 1; 
  border-radius: 24px; box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background-color: transparent;
}

/* ================= 独立底层：背景图片 ================= */
.bg-image-layer { position: absolute; inset: 0; z-index: 0; }
.bg-image-layer img { width: 100%; height: 100%; object-fit: cover; display: block; }

/* ================= 独立中层：颜色与毛玻璃遮罩 ================= */
.bg-mask-layer { position: absolute; inset: 0; z-index: 1; }

/* ================= 核心流式内容层 ================= */
.vibe-inner {
  position: relative; z-index: 2; 
  height: 100%; width: 100%;
  display: flex; flex-direction: column; 
  justify-content: space-between;
  padding: clamp(12px, 4vw, 16px); 
  box-sizing: border-box;
}

/* IG 风格胶囊贴纸公用类 */
.glass-pill {
  background-color: var(--pill-bg);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  border-radius: 99px; display: flex; align-items: center;
}

/* ================= 1. 顶部：定位贴纸与时间 ================= */
.vibe-header { display: flex; align-items: center; justify-content: space-between; flex-shrink: 0; }
.location-pill { gap: 4px; padding: clamp(4px, 1vw, 6px) clamp(8px, 2.5vw, 12px); }
.location-pill svg { width: clamp(10px, 3vw, 12px); height: clamp(10px, 3vw, 12px); color: var(--text-main); }
.location-pill span { font-size: clamp(9px, 2.5vw, 11px); font-weight: 700; color: var(--text-main); letter-spacing: 0.3px; }
.real-time { font-size: clamp(10px, 3vw, 12px); font-weight: 800; color: var(--text-sub); font-family: monospace; text-shadow: 0 1px 4px rgba(0,0,0,0.15); }

/* ================= 2. 中部：心情短语 ================= */
.vibe-center { flex: 1; display: flex; align-items: center; justify-content: center; text-align: center; overflow: hidden; }
.mood-text {
  font-size: clamp(16px, 5vw, 22px); font-weight: 800; color: var(--text-main);
  line-height: 1.2; letter-spacing: -0.5px;
  text-shadow: 0 2px 8px rgba(0,0,0,0.2); 
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}

/* ================= 3. 底部：用户与互动 ================= */
.vibe-footer { display: flex; align-items: center; justify-content: space-between; flex-shrink: 0; }
.user-pill { gap: 6px; padding: 3px clamp(10px, 3vw, 12px) 3px 3px; }
.avatar-mini { width: clamp(18px, 5vw, 22px); height: clamp(18px, 5vw, 22px); border-radius: 50%; overflow: hidden; background-color: rgba(0,0,0,0.1); flex-shrink: 0; }
.avatar-mini img { width: 100%; height: 100%; object-fit: cover; display: block; }
.user-name { font-size: clamp(10px, 2.8vw, 12px); font-weight: 600; color: var(--text-main); max-width: 60px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.action-icons { display: flex; align-items: center; gap: clamp(8px, 2.5vw, 12px); }
.action-icons svg { width: clamp(18px, 5vw, 22px); height: clamp(18px, 5vw, 22px); color: var(--icon-color); filter: drop-shadow(0 2px 4px rgba(0,0,0,0.15)); }

/* ================= 🌟 核心新增：爱心互动状态引擎 ================= */
.icon-heart {
  cursor: pointer;
  /* 平滑过渡线框颜色与缩放 */
  transition: transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275), fill 0.2s ease, stroke 0.2s ease;
}

/* 点亮之后的极致高光态 */
.icon-heart.liked {
  fill: #ff3040 !important;
  stroke: #ff3040 !important;
  filter: drop-shadow(0 2px 6px rgba(255, 48, 64, 0.45)) !important; /* 加上微弱的心动霓虹红光 */
  animation: heartPop 0.28s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

/* IG 经典的先张开再回弹微缩动效 */
@keyframes heartPop {
  0% { transform: scale(1); }
  50% { transform: scale(1.35); }
  100% { transform: scale(1.12); }
}

* { margin: 0; padding: 0; box-sizing: border-box; }
body { width: 100%; height: 100%; font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; }

.widget {
  --cap-bg: rgba(255,255,255,0.5);
  --cap-blur: 20px;
  width: 100%; height: 100%;
  display: flex; flex-direction: column; align-items: center;
  gap: 6px;
  padding: 8px;
}

/* 统一的可调背景层，铺在每个胶囊底部 */
.surface {
  position: absolute; inset: 0;
  background: var(--cap-bg);
  backdrop-filter: blur(var(--cap-blur)) saturate(180%);
  -webkit-backdrop-filter: blur(var(--cap-blur)) saturate(180%);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.35);
  border-radius: inherit;
  z-index: 1;
}

/* 电量这一行：两个独立胶囊并排 */
.cap-battery-row {
  width: 50%;
  flex: 0 0 30%;
  display: flex; align-items: center;
  gap: 6px;
}

.cap-battery-text {
  position: relative;
  flex: 1; height: 100%;
  border-radius: 999px;
  overflow: hidden;
}
.cap-content { position: relative; z-index: 2; height: 100%; display: flex; flex-direction: column; justify-content: center; padding: 0 16px; }
.battery-percent { font-size: 16px; font-weight: 800; color: #2b2b2f; line-height: 1.1; }
.battery-label { font-size: 9px; color: #8a8a90; margin-top: 2px; white-space: nowrap; }

.cap-battery-ring {
  position: relative;
  width: 44px; height: 44px; flex-shrink: 0;
  border-radius: 50%;
  overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.ring-content {
  position: relative;
  width: 26px;
  height: 26px;
  transform: rotate(-90deg);
  z-index: 2;
  display: block;
}
.ring-bg {
  fill: none;
  stroke: rgba(0, 0, 0, 0.1);
  stroke-width: 5;
}
.ring-fg {
  fill: none; stroke: #2b2b2f; stroke-width: 5; stroke-linecap: round;
  stroke-dasharray: 169.6; stroke-dashoffset: 169.6;
  transition: stroke-dashoffset .6s ease;
}

/* 头像信息胶囊 */
.cap-info-wrap { position: relative; width: 100%; flex: 0 0 40%; }
.stack-layer { position: absolute; left: 50%; transform: translateX(-50%); border-radius: 999px; }
.layer-3 { bottom: -8px; width: 88%; height: 60%; background: rgba(255,255,255,0.25); z-index: 1; }
.layer-2 { bottom: -4px; width: 94%; height: 75%; background: rgba(255,255,255,0.35); z-index: 2; }
.layer-1 { bottom: 0; width: 100%; height: 100%; z-index: 3; overflow: hidden; border-radius: 999px; }

.content {
  position: relative; z-index: 2; height: 100%;
  display: flex; align-items: center; padding: 0 18px; gap: 10px;
}
.avatar { width: 38px; height: 38px; border-radius: 50%; object-fit: cover; flex-shrink: 0; box-shadow: 0 2px 6px rgba(0,0,0,0.1); }
.text-wrapper { display: flex; flex-direction: column; gap: 3px; flex: 1; min-width: 0; }
.nickname { font-size: 13px; font-weight: 700; color: #2b2b2f; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.date { font-size: 10px; color: #9a9aa0; }
.time { font-size: 22px; font-weight: 800; color: #2b2b2f; flex-shrink: 0; }

/* 基礎透明背景重置 */
html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  background-color: transparent !important;
}

/* 主容器：啟用自適應尺寸 */
.widget-wrapper {
  position: relative; width: 100%; height: 100%;
  container-type: size;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  overflow: hidden;
}

/* 兔子與對話氣泡區塊 (右上角) */
.bunny-section {
  position: absolute; top: 4cqmin; right: 4cqmin;
  width: 42cqmin; display: flex; flex-direction: column;
  align-items: center; z-index: 10;
  /* 頭像再向上移動 3px (總共向上 13px) */
  transform: translateY(calc(-4cqmin - 13px)); 
}

/* 氣泡樣式 */
.bubble {
  background: #ffffff; padding: 3cqmin 4.5cqmin; border-radius: 5cqmin;
  font-size: 4.8cqmin; font-weight: 600; color: #333333;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 2.5cqmin;
  box-shadow: 0 1.5cqmin 4cqmin rgba(0, 0, 0, 0.08);
  position: relative;
  text-align: center;
  /* 氣泡向下移動 10px，完美壓在頭像上 */
  transform: translateY(13px);
  z-index: 2;
}
.bubble::after {
  content: ''; position: absolute; bottom: -2.5cqmin; right: 8cqmin; 
  border-width: 3.5cqmin 2.5cqmin 0; border-style: solid;
  border-color: #ffffff transparent transparent transparent;
}

/* 圖片容器 */
.image-box {
  width: 33cqmin; height: 33cqmin;
  background-color: rgba(255, 255, 255, 0.4); border: 0.8cqmin solid #ffffff;
  border-radius: 8cqmin; box-shadow: 0 2cqmin 6cqmin rgba(0, 0, 0, 0.06);
  overflow: hidden; box-sizing: border-box; display: flex;
  justify-content: center; align-items: center;
  z-index: 1; /* 確保圖片層級在氣泡下方 */
}
.image-box img {
  width: 100%; height: 100%; object-fit: cover; border-radius: 6.5cqmin;
}

/* Tabs (左中) */
.tabs {
  position: absolute; top: 26cqmin; left: 4cqmin; display: flex;
  background: rgba(255, 255, 255, 0.6); padding: 0.8cqmin;
  border-radius: 3cqmin; z-index: 5; backdrop-filter: blur(4px);

  transform: translateY(calc(1.2cqmin));
  cursor: pointer;
}
.tab {
  padding: 2.5cqmin 3.5cqmin; font-size: 4cqmin; font-weight: 600;
  color: #646b80;
}
.tab.active {
  background: #ffffff; color: #1a1d28; border-radius: 2cqmin;
  box-shadow: 0 1cqmin 2cqmin rgba(0,0,0,0.05);
}

/* 表單卡片 (左下) */
.form-card {
  position: absolute; bottom: 4cqmin; left: 4cqmin; width: 92cqmin;
  background: #ffffff; border-radius: 5cqmin; padding: 4.5cqmin;
  box-sizing: border-box; box-shadow: 0 3cqmin 10cqmin rgba(0, 0, 0, 0.06);
  z-index: 8;
}

.form-label {
  font-size: 4cqmin; font-weight: 700; color: #3b4255;
  margin-bottom: 2cqmin;
}
.form-input {
  border: 1px solid #ebedf2; border-radius: 2.5cqmin; padding: 2.5cqmin 3.5cqmin;
  font-size: 4.5cqmin; color: #2a2d3b; font-weight: 600;
  margin-bottom: 2cqmin;
}
.form-placeholder {
  font-size: 3.5cqmin; color: #939ab0; margin-bottom: 3.5cqmin;
}
.actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.btn-continue {
  background: #111424; color: #ffffff; padding: 2.5cqmin 4cqmin;
  border-radius: 2cqmin; font-size: 4cqmin; font-weight: 600;
  display: inline-block; cursor: pointer;
}
.forgot-password {
  font-size: 3.5cqmin;
  color: #646b80;
  cursor: pointer;
}
.hidden { display: none; }

/* 🌟 容器基础设定 */
.mz-android-widget {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 18px;
  background: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  font-family: sans-serif;
  -webkit-user-select: none;
  user-select: none;
}

/* 舞台区域 */
.stage-box {
  width: 100%;
  flex: 1;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  perspective: 700px;
  transform-style: preserve-3d;
}

/* 完美自适应卡片 */
.card-item {
  position: absolute;
  width: clamp(65px, 22%, 95px);
  aspect-ratio: 1 / 1.18;
  background-color: rgba(255, 255, 255, 0.65);

  /* 🌟 卡片毛玻璃特效 */
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);

  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 6px;
  box-sizing: border-box;
  transition: transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1), opacity 0.4s ease, z-index 0.4s step-start;
  cursor: pointer;

  /* 🌟 终极防溢出 Hack：切断边缘渲染泄露 */
  overflow: hidden;
  background-clip: padding-box;
  isolation: isolate;

  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

.img-wrap {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 6px;
  overflow: hidden;
  background: rgba(0,0,0,0.05);
  flex-shrink: 0;
}

.card-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.card-item img[src=""], .card-item img:not([src]) {
  display: none !important;
}

/* 歌名锁定底部 */
.song-name {
  width: 100%;
  margin-top: 2px;
  font-size: var(--song-size, 11px);
  color: #ffffff;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 2px rgba(0,0,0,0.4);
}

/* 3D 深度位置 */
.pos-0 { transform: translateX(0) translateZ(25px) scale(1); z-index: 10; opacity: 1; }
.pos-1 { transform: translateX(65%) translateZ(-40px) scale(0.85); z-index: 5; opacity: 0.8; }
.pos--1 { transform: translateX(-65%) translateZ(-40px) scale(0.85); z-index: 5; opacity: 0.8; }
.pos-2 { transform: translateX(115%) translateZ(-80px) scale(0.68); z-index: 1; opacity: 0.4; pointer-events: none; }
.pos--2 { transform: translateX(-115%) translateZ(-80px) scale(0.68); z-index: 1; opacity: 0.4; pointer-events: none; }

/* 底部控制舱毛玻璃特效 */
.bottom-panel {
  width: 88%;
  height: 36px;
  background: var(--panel-bg, rgba(255, 255, 255, 0.25));
  -webkit-backdrop-filter: blur(20px) saturate(150%);
  backdrop-filter: blur(20px) saturate(150%);
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  box-sizing: border-box;
  z-index: 30;
  flex-shrink: 0;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);

  /* 🌟 防溢出 Hack */
  overflow: hidden;
  background-clip: padding-box;
  isolation: isolate;
}

.panel-left, .panel-right {
  display: flex;
  align-items: center;
  gap: 10px;
}
.panel-right { justify-content: flex-end; }

.panel-center {
  flex: 1;
  text-align: center;
  color: var(--brand-color, #ffffff);
  font-size: var(--brand-size, 11px);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  background: transparent !important;
}

.ctrl-icon {
  width: 16px;
  height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.ctrl-icon svg {
  width: 100%;
  height: 100%;
  fill: var(--icon-color, #ffffff);
}
.ctrl-icon:active {
  transform: scale(0.85);
}

.heart-solid { display: none; fill: #ff2d55 !important; }
.ctrl-icon.liked .heart-hollow { display: none; }
.ctrl-icon.liked .heart-solid { display: block; }

.ctrl-icon[data-mode="0"] .mode-1, .ctrl-icon[data-mode="0"] .mode-2 { display: none; }
.ctrl-icon[data-mode="1"] .mode-0, .ctrl-icon[data-mode="1"] .mode-2 { display: none; }
.ctrl-icon[data-mode="2"] .mode-0, .ctrl-icon[data-mode="2"] .mode-1 { display: none; }

.mz-siri-widget-4x4 {
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  box-sizing: border-box;
}

.glass-blur {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  backdrop-filter: blur(35px) saturate(180%);
  -webkit-backdrop-filter: blur(35px) saturate(180%);
  z-index: 1; pointer-events: none;
  border-radius: 36px; overflow: hidden; 
  -webkit-clip-path: inset(0 round 36px); clip-path: inset(0 round 36px);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.15);
}

.glass-tint {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--bg-color); 
  opacity: 0.45; 
  z-index: 2; pointer-events: none;
  border-radius: 36px; overflow: hidden;
  -webkit-clip-path: inset(0 round 36px); clip-path: inset(0 round 36px);
}

.content {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  z-index: 3; 
  padding: 16px 20px; 
  display: flex; flex-direction: column;
}

.header-row {
  flex-shrink: 0; 
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 12px; 
}

.header-text {
  color: var(--header-color); 
  font-size: var(--header-size);
}
.header-text.left { font-weight: 600; }
.header-text.right { font-weight: 400; opacity: 0.8; }

.app-bubble {
  flex: 1 1 auto; 
  min-height: 0; 

  background-color: rgba(255, 255, 255, 0.12);
  border-radius: 28px;
  padding: 12px 16px; 
  display: flex; flex-direction: column; 
  justify-content: center;
  gap: 12px; 
}

.app-row {
  display: flex; justify-content: space-between; align-items: center;
}

.app-item {
  display: flex; flex-direction: column; align-items: center; 
  gap: 6px; 
  width: 23%; 
}

.app-icon-box {
  width: 100%; aspect-ratio: 1; 
  max-width: var(--icon-max-size, 56px); 
  max-height: var(--icon-max-size, 56px);
  border-radius: 22%; 
  overflow: hidden;
  box-shadow: 0 4px 10px rgba(0,0,0,0.1), inset 0 0 0 1px rgba(255,255,255,0.1);
}

.app-icon-box img {
  width: 100%; height: 100%; object-fit: cover;
}

.app-text {
  color: var(--app-color);
  font-size: var(--app-size);
  font-weight: 500;
  white-space: nowrap; 
}

.list-section {
  flex-shrink: 0; 
  display: flex; flex-direction: column; justify-content: center;
  padding: 0 10px;
  margin-top: 14px; 
}

.list-item {
  display: flex; align-items: center; gap: 14px;
  padding: 6px 0; 
}

.list-icon-box {
  width: 30px; height: 30px; 
  border-radius: 7px; overflow: hidden; flex-shrink: 0;
}

.list-icon-box img {
  width: 100%; height: 100%; object-fit: cover;
}

.list-text {
  color: var(--list-color);
  font-size: var(--list-size);
  font-weight: 600; flex-grow: 1;
}

.action-icon {
  width: 18px; height: 18px; 
  color: var(--action-icon-color);
  flex-shrink: 0;
}

.divider {
  width: auto; height: 1px; 
  background-color: var(--list-color); 
  opacity: 0.15;
  margin: 2px 0 2px 44px; 
}

value.css:
/*
 * iOS 原生日历风格byRABBIT
 * 使用：完整替换月历原有的自定义美化 CSS，不要与旧贴纸主题叠加。
 * 根据参考资料中已提供的 --cal-* 变量与类名编写。
 * 原应用负责日期、农历、事件、切月和按钮行为。
 */
:root {
  --ios-cal-red: #ff3b45;
  --ios-cal-ink: #111113;
  --ios-cal-muted: #8e8e93;
  --ios-cal-line: #e5e5ea;
  --ios-cal-blue: #91d6ee;
  --ios-cal-font: -apple-system, BlinkMacSystemFont, "Helvetica Neue",
    "PingFang SC", "PingFang TC", system-ui, sans-serif;

  --cal-font: var(--ios-cal-font);
  --cal-page-bg: #ffffff;
  --cal-page-bg-image: none;
  --cal-page-bg-size: cover;
  --cal-page-bg-position: center;
  --cal-page-padding: max(var(--nuo-safe-top, env(safe-area-inset-top, 0px)), 20px)
    16px calc(112px + env(safe-area-inset-bottom, 0px));
  --cal-ink: var(--ios-cal-ink);
  --cal-ink-muted: var(--ios-cal-muted);
  --cal-accent: var(--ios-cal-red);

  --cal-title-color: var(--ios-cal-ink);
  --cal-title-size: 2.15rem;
  --cal-title-weight: 750;
  --cal-title-letter-spacing: -1px;
  --cal-title-font: var(--ios-cal-font);
  --cal-topbar-gap: 14px;
  --cal-avatar-size: 36px;
  --cal-avatar-radius: 50%;
  --cal-avatar-border: 1px solid #eeeeef;
  --cal-avatar-shadow: none;

  --cal-week-color: var(--ios-cal-ink);
  --cal-week-size: 0.72rem;
  --cal-week-weight: 400;
  --cal-week-transform: none;
  --cal-grid-gap: 0px;
  --cal-grid-margin-bottom: 22px;

  --cal-day-bg: transparent;
  --cal-day-radius: 0px;
