  background: none !important;
  text-shadow: none !important;
  font-size: var(--cal-daynum-size);
}
.nuo-cal-day.birthday-day::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: auto auto -8px 50% !important;
  width: 5px !important;
  height: 5px !important;
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  border-radius: 50% !important;
  background: var(--ios-cal-blue) !important;
  box-shadow: none !important;
  transform: translateX(-50%) !important;
  animation: none !important;
  pointer-events: none;
}
.nuo-cal-day.birthday-day.today {
  background: var(--ios-cal-red) !important;
}
.nuo-cal-day.birthday-day.today :is(.nuo-cal-daynum, .day-number) {
  color: #fff !important;
}
.nuo-cal-cell:is([data-selected="true"], [data-selected=""], [data-selected="1"]) .nuo-cal-day.birthday-day {
  outline: 1.5px solid #b8b8bd;
  outline-offset: 2px;
}
/* 导航底板透明；原定位与点击行为由宿主保持。 */
.nuo-cal-nav {
  background: transparent !important;
