    --cal-modal-shadow: 0 18px 60px rgba(0,0,0,.55);
    --cal-menu-bg: #252527;
    --cal-menu-shadow: 0 8px 32px rgba(0,0,0,.45);
    --cal-vcal-bg: #2c2c2e;
    --cal-vcal-sub-color: #aeaeb5;
    --cal-now-pill-bg: #3c2023;
    --cal-now-pill-color: #ff6961;
    --cal-tl-line: #38383d;
    --cal-tl-dot-border: 2px solid #000;
    --cal-char-avatar-border: 1px solid #38383d;
    --cal-bubble-border-color: #38383d;
    --cal-bubble-sub-color: #aeaeb5;
    --cal-timeline-ai-bg: #1c1c1e;
    --cal-timeline-user-bg: #1c1c1e;
    --cal-agenda-bg: #242426;
