    --cal-todo-panel-bg: #1c1c1e;
    --cal-todo-panel-shadow: 0 -8px 40px rgba(0,0,0,.45);
    --cal-todo-check-bg: #2c2c2e;
    --cal-todo-check-border: 1.5px solid #98989f;
    --cal-memory-bg: #000;
    --cal-report-bg: #1c1c1e;
    --cal-polaroid-bg: #1c1c1e;
    --cal-polaroid-border: 1px solid #38383d;
    --cal-polaroid-img-bg: #2c2c2e;
    --cal-badge-avatar-bg: #2c2c2e;
    --cal-badge-avatar-border: 2px solid #1c1c1e;
    --cal-letter-bg: #1c1c1e;
  }
  .nuo-cal-root,
  .nuo-cal-month,
  .nuo-cal-timeline,
  .nuo-cal-timeline-ai,
  .nuo-cal-timeline-user,
  .nuo-cal-memory {
    color-scheme: dark;
    color: var(--ios-cal-ink);
    background-color: #000;
  }
  .nuo-cal-title, .month-title {
    color: var(--ios-cal-ink);
  }
  .nuo-cal-topbar .back-icon,
  .nuo-cal-topbar .header-actions,
  .nuo-cal-nav .nuo-cal-nav-btn,
  .nuo-cal-nav .nuo-cal-add {
    background: var(--ios-night-glass);
