}
.input-box-custom{
  margin-left:var(--input-box-pull-left)!important;
  margin-right:var(--input-box-pull-right)!important;
  text-align:left!important;
  padding-left:var(--input-text-padding-left)!important;
  padding-right:10px!important;
clip-path: inset(var(--box-top-offset) 0 var(--box-bottom-offset) 0) !important;
}
.input-box-custom::selection,
.input-box-custom *::selection{
