    -webkit-backdrop-filter:blur(10px) saturate(180%)!important;
  }
}
@media (prefers-color-scheme: dark) {
  body .input-reply-preview-bar{
    background:var(--input-reply-bar-bg)!important;
    background-color:var(--input-reply-bar-bg)!important;
    background-image:none!important;
    border:var(--input-reply-bar-border)!important;
    backdrop-filter:blur(10px) saturate(180%)!important;
    -webkit-backdrop-filter:blur(10px) saturate(180%)!important;
  }
}
body .input-reply-preview-name,
body .input-reply-preview-name::after{
  color:var(--input-reply-bar-name-color)!important;
