  font-weight: 600;
  color: #303338;
  padding: 2px 7px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.35);
  border: 1px solid rgba(0, 0, 0, 0);
  line-height: 1.2;
}

/* 底部通知中心 */
.notification-center {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 95px;
  z-index: 5;
}

.nc-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  padding: 0 4px;
}

.nc-title {
  font-size: 18px;
  font-weight: 700;
  color: #303338;
  letter-spacing: -0.3px;
  text-shadow: 0 2px 8px rgba(255, 255, 255, 0.4);
}

.nc-close {
  width: 25px;
  height: 25px;
  border-radius: 50%;
  box-sizing: border-box; /* 核心：锁定尺寸，加内边距绝不变形 */

  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  border: 1px solid rgba(0, 0, 0, 0);

  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: rgba(48, 51, 56, 0.85);

  /* 内部 ✕ 偏下时：用底部内边距向上顶（数值越大越往上） */
  padding-bottom: 2px; 
}


.nc-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 20px;
  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(25px) saturate(190%);
  -webkit-backdrop-filter: blur(25px) saturate(190%);
  border: 1px solid rgba(0, 0, 0, 0);
  box-shadow: 0 10px 30px rgba(255, 255, 255, 0.2);
}

.nc-avatar {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.2) url("{{img2}}") center / cover no-repeat;
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(255, 255, 255, 0.2);
}

.nc-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.nc-top-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.nc-name {
  font-size: 15px;
  font-weight: 600;
  color: #303338;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.3);
}

.nc-time {
  font-size: 12px;
  color: rgba(48, 51, 56, 0.7);
}

.nc-message {
  font-size: 14px;
  color: rgba(48, 51, 56, 0.95);
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 2px rgba(255, 255, 255, 0.3);
}

/* 底部快捷按键容器 */
.bottom-bar {
  position: absolute;
  left: 46px;
  right: 46px;
  bottom: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 10;
}

/* 1. 外层玻璃圆盘底座 */
.action-btn {
  width: 55px;
  height: 55px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  border: 1px solid rgba(0, 0, 0, 0);
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  color: #303338;
  box-shadow: 0 4px 12px rgba(255, 255, 255, 0.25);
  box-sizing: border-box;
}

/* 2. 内部网络图片图标基础设置 */
.btn-icon {
  width: 28px;  /* 图标全局大小 */
  height: 28px;
  display: block;
  background-position: center;
  background-size: contain;
  background-repeat: no-repeat;
  margin: 0;
}

/* 3. 单独微调偏移量（根据视觉感觉修改数值） */

/* 手电筒图标 */
.action-btn[data-app="1"] .btn-icon {
  transform: translate(1px, 1px); /* (左右, 上下) 负数往左/上，正数往右/下 */
}

/* 相机图标 */
.action-btn[data-app="2"] .btn-icon {
  transform: translate(0px, -1px); /* (左右, 上下) 负数往左/上，正数往右/下 */
}

/* 微信_切换日夜间7by池谕 — nuojiji messaging app theme */

/* ==========================================
