/* 基础变黑 */
#messaging-chat-tab[data-color-scheme="dark"],
#messaging-moments-tab[data-color-scheme="dark"],
#messaging-profile-tab[data-color-scheme="dark"],
#messaging-favorites-tab[data-color-scheme="dark"],
[data-color-scheme="dark"] {
    --nj-msg-bg: #111111 !important;
    --nj-msg-chat-bg: #111111 !important;
    --nj-msg-text: #ffffff !important;
    --nj-msg-text-muted: #888888 !important;
    --nj-msg-card-bg: #111111 !important;
    --nj-msg-card-bg-pinned: #212121 !important;
    --nj-msg-tabbar-bg: #1a1a1a !important;
    --nj-msg-tabbar-inactive: #888888 !important;
}

/* 聊天列表夜间 */
[data-color-scheme="dark"] .nj-chat-tab-list {
    background: #171717 !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header {
    background: #111111 !important;
}
[data-color-scheme="dark"] .nj-chat-tab-search {
    background: #1a1a1a !important;
}
[data-color-scheme="dark"] .nj-chat-item:not(.nj-chat-item-pinned) {
    background-color: #171717 !important;
}
[data-color-scheme="dark"] .nj-chat-item:active {
    background-color: #2c2c2c !important;
}
[data-color-scheme="dark"] .nj-chat-item-avatar-group-grid {
    background: #2c2c2c !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header::after {
    color: #ffffff !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header-edit {
    filter: invert(1) !important;
}
[data-color-scheme="dark"] .nj-chat-tab-search::after {
    background-color: #1a1a1a !important;
}

/* 朋友圈夜间 */
[data-color-scheme="dark"] #messaging-moments-tab,
[data-color-scheme="dark"] .nj-moments-feed,
[data-color-scheme="dark"] .nj-moments-post {
    background-color: #1a1a1a !important;
}
[data-color-scheme="dark"] .nj-moments-engagement {
    background-color: #2c2c2c !important;
}
[data-color-scheme="dark"] .nj-moments-post {
    border-bottom: 0.5px solid rgba(255,255,255,0.05) !important;
}
[data-color-scheme="dark"] .nj-moments-post-name,
[data-color-scheme="dark"] .nj-moments-engagement a,
[data-color-scheme="dark"] .nj-moments-engagement [class*="author"],
[data-color-scheme="dark"] .nj-moments-engagement [class*="target"],
[data-color-scheme="dark"] .nj-moments-engagement [class*="like"],
[data-color-scheme="dark"] .nj-moments-engagement [class*="name"] {
    color: #7b90b2 !important;
}
[data-color-scheme="dark"] .nj-moments-post-text {
    color: rgba(255,255,255,0.85) !important;
}
[data-color-scheme="dark"] .nj-moments-comment-content {
    color: rgba(232, 232, 232, 0.85) !important;
}
/* 白天模式的底座和点点 */
.nj-moments-post-actions-trigger {
background: #f7f7f7 !important;
width: 30px !important;
height: 18px !important;
border-radius: 4px !important;
display: flex !important;
justify-content: center !important;
align-items: center !important;
color: #576b95 !important;/* 🔵蓝点 */
font-size: 21px !important;/* 🔵蓝点大小 */
letter-spacing: -11px !important;/* 🔵蓝点间距 */
padding-right: 10px !important;/* 🔵蓝点左右 */
}

/* 夜间模式单独适配 */
[data-color-scheme="dark"] .nj-moments-post-actions-trigger {
background: #2c2c2c !important;
color: #8b95a1 !important;
}

/* 个人主页夜间强杀白斑 */
[data-color-scheme="dark"] #messaging-profile-tab,
[data-color-scheme="dark"] .nj-profile-tab-header {
    background-color: #111111 !important;
    color: #ffffff !important;
}
[data-color-scheme="dark"] .nj-profile-tab-header svg {
    color: #ffffff !important;
    stroke: #ffffff !important;
    fill: none !important;
}
[data-color-scheme="dark"] .nj-profile-hobby-chip {
    background-color: #2c2c2c !important;
    color: #dddddd !important;
}
[data-color-scheme="dark"] .nj-profile-info-icon,
[data-color-scheme="dark"] .nj-profile-gallery-cell {
    background-color: #2c2c2c !important;
}
[data-color-scheme="dark"] .nj-profile-info-bar {
    background-color: #1a1a1a !important;
}
[data-color-scheme="dark"] .nj-profile-about-text::after,
[data-color-scheme="dark"] .nj-profile-about::after {
    background: linear-gradient(to bottom, rgba(17,17,17,0), #111111) !important;
}

/* 底栏夜间 */
[data-color-scheme="dark"] .nj-tab-bottom-bar {
    border-top: 0.5px solid #2c2c2c !important;
    background: rgba(31, 31, 31, 0.9) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
}

[data-color-scheme="dark"] .nj-tab-bottom-item::after {
    color: #888888 !important;
}
[data-color-scheme="dark"] .nj-tab-bottom-item-active::after {
    color: #07c160 !important;
}
/* 去渐变遮挡 */
.nj-profile-about-fade { display: none !important; }
/* ==========================================
   伪造 iPad 微信已登录横幅 (靠左对齐版)
========================================== */

/* 横幅容器：靠左对齐，调整高度和边距 */
.nj-chat-tab-decor-top {
    display: flex !important;
    justify-content: flex-start !important; /* 靠左对齐 */
    align-items: center !important;
    /* 【调位置看这里】
       20px 管高度：数字越大横幅越宽
       30px 管左右：数字越大越往右缩
    */
    padding: 22px 28px !important; 
    background-color: #ededed !important; 
    border-bottom: 0.5px solid #d6d6d6 !important;
    gap: 24px !important;
}

/* 左侧：高仿 iPad 线条图标 */
.nj-chat-tab-decor-top::before {
    content: '' !important;
    display: block !important;
    transform: translateY(0px) !important;
    width: 22px !important;
    height: 22px !important;
    background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23737373" stroke-width="1.2" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="5" width="18" height="14" rx="1.5"/><path d="M10 16h4"/></svg>') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}

/* 右侧：文字 */
.nj-chat-tab-decor-top::after {
    content: 'iPad 微信已登录' !important;
    font-size: 13px !important;
    color: #737373 !important;
    transform: translateY(0px) !important;
}

/* --- 夜间模式适配 --- */
[data-color-scheme="dark"] .nj-chat-tab-decor-top {
    background-color: #212121 !important;
    border-bottom: 0.5px solid #383838 !important;
}
[data-color-scheme="dark"] .nj-chat-tab-decor-top::before {
    background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23888888" stroke-width="1.2" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="5" width="18" height="14" rx="1.5"/><path d="M10 16h4"/></svg>') !important;
}
[data-color-scheme="dark"] .nj-chat-tab-decor-top::after {
    color: #888888 !important;
}
/* ==========================================
   朋友圈封面：黑渐变 + 微信原味头像
========================================== */


/* 封面右下角头像 */
.nj-moments-cover-avatar {
    border-radius: 7px !important;
    right: 30px !important;
    bottom: -20px !important;
    border: 0px solid #ffffff !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1) !important;
}

/* 封面用户名 */
.nj-moments-cover-username {
    color: #ffffff !important;
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.3) !important; /* 加点阴影防看不清 */
    right: 100px !important; /* 根据头像宽度微调，别和头像撞上 */
    bottom: 12px !important;
}
/* 朋友圈封面渐变：多层过渡，越往上越浅 */
.nj-moments-cover-gradient {
    background: linear-gradient(to top, rgba(0, 0, 0, 0.35) 0%, rgba(0, 0, 0, 0.05) 45%, transparent 100%) !important;
    height: 60px !important;
}

/* 缩小封面头像 */
.nj-moments-cover-avatar {
    width: 75px !important;
    height: 75px !important;
    right: 16px !important;
    transform: translateY(-7px) !important;
}

/* 名字跟着头像稍微往右靠一点 */
.nj-moments-cover-username {
    right: 96px !important;
}

/* 缩小朋友圈列表里的头像 */
.nj-moments-post-avatar {
    width: 42px !important;
    height: 42px !important;
    margin-left: 4px !important;
    margin-right: -2px !important;
    border-radius: 4px !important;
}

/* 时间和回复按钮一起往上挪 */
.nj-moments-post-time,
.nj-moments-post-actions-trigger,
.nj-moments-post-time + span,
.nj-moments-post-time + div:not(.nj-moments-engagement) {
    transform: translateY(-7px) !important; 
}
/* 缩小封面和第一条动态的间距 */
.nj-moments-feed {padding-top: 0px !important;}

/* ==========================================
朋友圈顶栏 (高度钉死版)
========================================== */
/* 白天模式 */
.nj-moments-header-sticky {
    display: flex !important;
    align-items: flex-end !important; /* 强制里面的图标靠下对齐 */
    background: rgba(237, 237, 237, 0.85) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    border-bottom: none !important; 
    box-shadow: none !important; 
    height: calc(40px + var(--nuo-safe-top)) !important; /* 强行写死高度 */
    padding-top: 0 !important;
    padding-bottom: 11px !important; /* 图标距离底部的距离，觉得高了就改小 */
    box-sizing: border-box !important;
}
.nj-moments-header {
    display: flex !important;
    align-items: flex-end !important;
    height: calc(40px + var(--nuo-safe-top)) !important;
    padding-top: 0 !important;
    padding-bottom: 10px !important;
    box-sizing: border-box !important;
}
/* 夜间模式 */
[data-color-scheme="dark"] .nj-moments-header-sticky {
    background: rgba(17, 17, 17, 0.85) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
}

/* ==========================================
   修复底栏毛玻璃透色 (日夜双模式，安全高度版)
========================================== */
/* 夜间模式：聊天、主页、收藏用深灰底板，高度450避开搜索栏 */
[data-color-scheme="dark"] #messaging-chat-tab::after,
[data-color-scheme="dark"] #messaging-profile-tab::after,
[data-color-scheme="dark"] #messaging-favorites-tab::after {
    content: '' !important;
    position: fixed !important;
    left: 0 !important; right: 0 !important; bottom: 0 !important;
    height: 450px !important; 
    background-color: #171717 !important;
    z-index: -1 !important;
    pointer-events: none !important;
}

/* 朋友圈专属底板：颜色改纯黑，高度直接拉满全屏！ */
[data-color-scheme="dark"] #messaging-moments-tab::after {
    content: '' !important;
    position: fixed !important;
    left: 0 !important; right: 0 !important; bottom: 0 !important;
    height: 75vh !important; /* 100vh就是填满整个屏幕的高度 */
    background-color: #1a1a1a !important; /* 和朋友圈背景融为一体 */
    z-index: -1 !important;
    pointer-events: none !important;
}

/* 白天模式：纯白底板 */
[data-color-scheme="light"] #messaging-chat-tab::after,
[data-color-scheme="light"] #messaging-moments-tab::after,
[data-color-scheme="light"] #messaging-profile-tab::after,
[data-color-scheme="light"] #messaging-favorites-tab::after {
    content: '' !important;
    position: fixed !important;
    left: 0 !important; right: 0 !important; bottom: 0 !important;
    height: 750px !important;
    background-color: #ffffff !important;
    z-index: -1 !important;
    pointer-events: none !important;
}

.nj-chat-tab-search-wrap {
    background-color: #ededed !important;
}
[data-color-scheme="dark"] .nj-chat-tab-search-wrap {
    background-color: #111111 !important;
}

/* 修复切换账号按钮位置 */
.nj-chat-tab-header-title-btn {
    position: absolute !important;
    left: 50% !important;
    top: calc(17px + var(--nuo-safe-top)) !important;
    transform: translate(-50%, -50%) !important;
    width: 100px !important; 
    height: 40px !important;
    z-index: 110 !important;
}

/* 微信_切换日夜间7by池谕 — nuojiji messaging app theme */

/* ==========================================
   糯叽机 · 微信高仿主题终整理版
========================================== */

/* ========== 1. 全局变量与基础底色 ========== */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
    --nj-msg-bg: #ededed;
    --nj-msg-chat-bg: #ffffff;
    --nj-msg-card-bg: #ffffff;
    --nj-msg-card-bg-pinned: #efefef;
    --nj-msg-card-radius: 0px;
    --nj-msg-card-border: none;
    --nj-msg-card-gap: 0px;
    --nj-msg-text: #191919;
    --nj-msg-text-muted: #b2b2b2;
    --nj-msg-text-time: #b2b2b2;
    --nj-msg-avatar-radius: 5px;
    --nj-msg-avatar-shadow: none;
    --nj-msg-tabbar-active: #07c160;
    --nj-msg-tabbar-bg: #f7f7f7;
    --nj-msg-card-active-transform: none;
    --nj-msg-card-hover-transform: none;
    --nj-msg-card-transition: background-color 0.1s;
    --nj-msg-moments-cover-height: 350px;
/* 👇 小白设置区：左上角五角星开关 👇 */
/* 填 block 是显示，填 none 是隐藏 */
    --show-top-star: block;
}


/* ========== 2. 聊天列表 (微信首页) ========== */
/* 解决色差：正规撑满大法 */
#messaging-chat-tab {
    display: flex !important;
    flex-direction: column !important;
    --nj-msg-chat-bg: #ededed !important;
}
.nj-chat-tab-list {
    flex-grow: 1 !important;
    background: #ffffff !important;
    padding-bottom: calc(-5px + var(--nuo-safe-bottom)) !important;
}

/* 聊天列表项与间距 */
.nj-chat-item {
    margin: 0 !important;
    padding: 12px 16px !important;
    box-shadow: none !important;
    position: relative !important;
}
.nj-chat-item:active {
    background-color: #d9d9d9 !important;
}
.nj-chat-item-name {
    margin-bottom: 0px !important; 
    line-height: 1.2 !important;
}
.nj-chat-item-preview {
    margin-top: 4.5px !important;
    line-height: 1.2 !important;
    margin-right: 3px !important;
    text-overflow: ellipsis !important;
    display: block !important;
}
.nj-chat-item-time {
    font-size: 11px !important; 
    font-weight: 420 !important;
    color: #999999 !important;
    opacity: 0.5 !important; 
    transform: translateY(-2px) !important; 
}
/* 去大头钉 */
.nj-chat-item-pin-mark { display: none !important; }
/* 微信原味短分割线（避开头像） */
.nj-chat-item::after {
content: '' !important;
position: absolute !important;
bottom: 0 !important;
left: 74px !important;
right: 0 !important;
height: 0.2px !important;
background-color: #d6d6d6 !important;
z-index: 1 !important;
}
/* 夜间模式短线 */
[data-color-scheme="dark"] .nj-chat-item::after {
background-color: #383838 !important;
}

/* 头像样式 */
.nj-chat-item-avatar {
    width: 46px !important;
    height: 46px !important;
    margin-right: 13px !important; 
}
.nj-chat-item-avatar-group-grid {
    width: 46px !important;
    height: 46px !important;
    background: #dddddd !important;
    border-radius: 4px !important;
    padding: 2px !important;
    gap: 2px !important;
}
.nj-chat-item-avatar-group-cell {
    border-radius: 2px !important;
}

/* 隐藏多余元素 */
.nj-chat-tab-notes,
.nj-chat-tab-section-title {
    display: none !important;
}

/* 自动切换日夜间版 */
.nj-chat-tab-header {
    background: #ededed !important;
    border-bottom: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    height: calc(40px + var(--nuo-safe-top)) !important;
    padding: 0 !important;
    position: sticky !important;
    top: 0 !important;
    z-index: 100 !important;
}
.nj-chat-tab-header-title-btn {
    color: transparent !important;
}
.nj-chat-tab-header::after {
    content: '微信';
    position: absolute !important;
    left: 50% !important;
    top: calc(18px + var(--nuo-safe-top)) !important;
    transform: translate(-50%, -50%) !important;
    font-size: 17px;
    font-weight: 500;
    color: #191919;
    pointer-events: none;
}
.nj-chat-tab-header-edit svg {
    display: none !important;
}
.nj-chat-tab-header-edit {
    background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23191919" stroke-width="1.5" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="9.5"></circle><path d="M12 7.5v9M7.5 12h9"></path></svg>');
    background-size: 22px;
    background-repeat: no-repeat;
    background-position: center;
    width: 24px !important;
    height: 24px !important;
    position: absolute !important;
    right: 16px !important;
    top: calc(17px + var(--nuo-safe-top)) !important;
    transform: translateY(-50%) !important;
}
.nj-chat-tab-header-back svg {
    display: none !important;
}
.nj-chat-tab-header-back {
    opacity: 1 !important;
    display: var(--show-top-star) !important;
    background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23191919" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" xmlns="http://www.w3.org/2000/svg"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>');
    background-size: 22px;
    background-repeat: no-repeat;
    background-position: center;
    width: 24px !important;
    height: 24px !important;
    position: absolute !important;
    left: 16px !important;
    top: calc(17px + var(--nuo-safe-top)) !important;
    transform: translateY(-50%) !important;
}
/* 夜间模式五角星变白 */
[data-color-scheme="dark"] .nj-chat-tab-header-back {
    filter: invert(1) !important;
}

/* 搜索框本体与假盖子 */
.nj-chat-tab-search {
    background: #ffffff !important;
    border-radius: 7px !important;
    margin:-7px -11px 5px -11px !important;
    height: 34px !important;
    box-shadow: 0 0px 12px rgba(0, 0, 0, 0.01) !important;
    border: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    padding: 0 12px !important;
    position: relative !important;
}
.nj-chat-tab-search > svg {
    display: none !important;
}
.nj-chat-tab-search::after {
    content: '搜索';
    position: absolute !important;
    left: 0 !important;
    right: 0 !important;
    top: 0 !important;
    bottom: 0 !important;
    background-color: #ffffff !important;
    border-radius: 7px !important;
    z-index: 10 !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    color: #b2b2b2 !important;
    font-size: 15px !important;
    pointer-events: none !important;
    padding-left: 20px !important;
    background-image: url('data:image/svg+xml;utf8,<svg viewBox="0 0 24 24" fill="none" stroke="%23999999" stroke-width="2" xmlns="http://www.w3.org/2000/svg"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg>');
    background-repeat: no-repeat !important;
    background-size: 15px !important;
    background-position: calc(50% - 17px) calc(50% - 1px) !important;
}
.nj-chat-tab-search:focus-within::after {
    display: none !important;
}


/* ========== 3. 朋友圈 ========== */
/* 强制白底与紧凑布局 */
#messaging-moments-tab,
.nj-moments-feed,
.nj-moments-post {
    background-color: #ffffff !important;
}
.nj-moments-post {
    padding-top: 14px !important;
    padding-bottom: 8px !important;
    padding-left: 16px !important;
    padding-right: 22px !important;
    border-bottom: 0.5px solid rgba(0,0,0,0.05) !important;
}
.nj-moments-post-text {
    font-size: 15px !important;
    color: #1a1a1a !important;
    margin-top: -2px !important;
}
.nj-moments-post-imgs {
    margin-top: -6px !important;
    gap: 4px !important;
    padding-bottom: 6px !important;
    margin-left: -2px !important; /* 👈 新加的，负数就是往左拽，数字越大拽得越狠 */
}

/* 1. 灰框：把左边的棉花掏掉 */
.nj-moments-engagement {
    background-color: #f7f7f7 !important;
    border-radius: 6px !important;
    overflow: hidden !important;
    margin-top: 5px !important;
    margin-bottom: 10px !important;
    transform: translateX(-3px) !important;
    width: calc(100% + 3px) !important;
    padding-left: 0px !important;
    padding-right: 0px !important;
    padding-bottom: 4px !important;
    padding-top: 6px !important;
}

/* 2. 点赞行：线拉满了，字往右挤 */
