}


/* =========================================================
   11. 语音 / 翻译
   ========================================================= */

.tm-voice-controls {
  margin-top: 10px !important;
}

.tm-voice-btn {
  background: rgba(255,255,255,0.82) !important;
  border: 1px solid #d0d0cc !important;
