  box-shadow: 0 -6px 22px rgba(0,0,0,0.05) !important;
}

.tm-compose-toolbar {
  gap: 7px !important;
}

.tm-regen-btn,
.tm-suggestions-btn {
  background: rgba(255,255,255,0.82) !important;
  border: 1px solid #cececa !important;
  border-radius: 999px !important;
