/* =========================================================
   NUOJIJI UNIVERSITY · 波点学生证 by薄荷猫
   This Moment Classic Theme
   灵感来源xhs@我们焚烧 的eve线下番外 🈲二传二改
   ========================================================= */


/* =========================================================
   0. 主题变量
   ========================================================= */

:root {
  --id-card-width: min(90vw, 720px);
  --id-body-max-height: 430px;

  --id-bg: #f4f2ee;
  --id-paper: rgba(255, 255, 255, 0.92);
  --id-card: #fdfdfb;
  --id-line: #d8d8d4;

  --id-ink: #333333;
  --id-sub: #777777;
  --id-gray: #8f8f8f;
  --id-gray-dark: #555555;

  --id-radius: 10px;
  --id-small-radius: 5px;

  --id-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  --id-soft-shadow: 0 4px 12px rgba(0, 0, 0, 0.06);

  --id-scroll-thumb: rgba(0, 0, 0, 0.14);
  --id-scroll-thumb-hover: rgba(0, 0, 0, 0.28);

  /* 【可改：头像大小】数值越大头像越大 */
  --id-avatar-w: 110px;
  --id-avatar-h: 142px;

  /* 【可改：头像位置】数值越小越靠左 */
  --id-avatar-left: 20px;
  --id-avatar-top: 78px;

  /* 【可改：右侧姓名信息位置】数值越大越靠右 */
  --id-info-left: 178px;

  /* 【可改：学生证高度】头像变大后这里也要适当变大 */
  --id-header-height: 262px;
}


/* =========================================================
   1. 页面背景
   ========================================================= */

.tm-bg-overlay {
  background:
    radial-gradient(circle at 15% 8%, rgba(255,255,255,0.9), transparent 34%),
    radial-gradient(circle at 85% 92%, rgba(190,190,185,0.25), transparent 40%),
    linear-gradient(180deg, #faf9f6 0%, var(--id-bg) 100%) !important;
}

.tm-bg-image {
  filter: blur(34px) grayscale(18%) brightness(1.12) !important;
  opacity: 0.16 !important;
  transform: scale(1.08) !important;
}

.tc-watermark {
  display: block !important;
  opacity: 0.045 !important;
  background-image: radial-gradient(circle, #555 1px, transparent 1.5px) !important;
  background-size: 14px 14px !important;
}


/* =========================================================
   2. 顶部导航栏
   ========================================================= */

.tm-header {
  background: rgba(255, 255, 255, 0.76) !important;
  border-bottom: 1px solid rgba(185,185,180,0.55) !important;
  backdrop-filter: blur(18px) !important;
  -webkit-backdrop-filter: blur(18px) !important;
  box-shadow: 0 4px 18px rgba(0,0,0,0.04) !important;
}

.tm-btn-icon,
.tm-top-drop-btn,
.tm-top-drop-btn-user {
  background: rgba(255,255,255,0.72) !important;
  border: 1px solid rgba(190,190,185,0.65) !important;
  border-radius: 999px !important;
  color: var(--id-gray-dark) !important;
}

.tm-btn-icon svg,
.tm-top-drop-btn svg,
.tm-top-drop-btn-user svg {
  color: var(--id-gray-dark) !important;
  stroke: var(--id-gray-dark) !important;
}

.tm-header-name {
  color: #4d4d4d !important;
  font-weight: 700 !important;
  letter-spacing: 0.3px !important;
}

.tm-header-avatar {
  border-radius: 5px !important;
  border: 1px solid #ffffff !important;
  box-shadow: 0 1px 5px rgba(0,0,0,0.16) !important;
}

.tm-top-vs {
  color: #999 !important;
  font-weight: 700 !important;
}


/* =========================================================
   3. 故事区
   ========================================================= */

.tm-story {
  padding: 14px 14px 82px 14px !important;
}

.tm-story::-webkit-scrollbar {
  width: 6px !important;
}

.tm-story::-webkit-scrollbar-track {
  background: transparent !important;
}

.tm-story::-webkit-scrollbar-thumb {
  background: rgba(0,0,0,0.16) !important;
  border-radius: 999px !important;
}

.tm-load-more {
  width: fit-content !important;
  margin: 6px auto 14px auto !important;
  padding: 6px 16px !important;
  background: rgba(255,255,255,0.72) !important;
  color: #777 !important;
  border: 1px dashed #b9b9b5 !important;
  border-radius: 999px !important;
  font-size: 12px !important;
}


/* =========================================================
   4. 每条消息整体：居中 + 缩小间距
   ========================================================= */

.tm-para {
  position: relative !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  width: 100% !important;

  /* 【可改：上下两条消息间距】数值越小，两条越近 */
  margin: 2px auto !important;

  padding-top: 0 !important;
}

.tm-para-char,
.tm-para-user {
  position: relative !important;

  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  justify-content: flex-start !important;

  width: var(--id-card-width) !important;
  max-width: var(--id-card-width) !important;
  margin-left: auto !important;
  margin-right: auto !important;
  align-self: center !important;

  background-color: var(--id-paper) !important;
  background-image:
    radial-gradient(circle, rgba(160,160,160,0.5) 1px, transparent 1.35px),
    linear-gradient(rgba(222,222,218,0.9) 1px, transparent 1px) !important;
  background-size: 15px 15px, 100% 1.65em !important;
  background-attachment: local !important;

  border: 1px solid var(--id-line) !important;
  border-radius: var(--id-radius) !important;
  box-shadow: var(--id-shadow) !important;

  padding: 9px 14px 9px 14px !important;
  color: var(--id-ink) !important;

  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;

  max-height: none !important;
  overflow: visible !important;
}


/* 删除 char / user 顶部胶带 */
.tm-para-char::before,
.tm-para-user::before {
  display: none !important;
  content: none !important;
}


/* =========================================================
   5. 学生证 Header：char 与 user 共用
   ========================================================= */

.tc-header,
.tc-header-user {
  position: relative !important;
  z-index: 5 !important;
  overflow: hidden !important;
  flex-shrink: 0 !important;

  width: 100% !important;
  min-height: var(--id-header-height) !important;
  box-sizing: border-box !important;

  background: var(--id-card) !important;
  border: 1px solid #e0e0dc !important;
  border-radius: 9px !important;
  box-shadow: var(--id-soft-shadow) !important;

  padding: 68px 14px 10px 14px !important;
  margin-bottom: 6px !important;
}


/* 顶部灰色栏 */
.tc-header::before,
.tc-header-user::before {
  /* 【可改：学生证顶部大标题】 */
  content: "NUOJIJI UNIVERSITY" !important;

  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  z-index: 1 !important;

  width: 100% !important;
  height: 54px !important;
  box-sizing: border-box !important;
  padding-left: 15px !important;

  background: #909090 !important;
  color: #ffffff !important;

  font-size: 16px !important;
  font-weight: 900 !important;
  letter-spacing: 0.8px !important;
  line-height: 36px !important;
}


/* 顶部副标题 */
.tc-header::after,
.tc-header-user::after {
  /* 【可改：学生证顶部副标题】 */
  content: "INTERNATIONAL STUDENT ID CARD" !important;

  position: absolute !important;
  top: 31px !important;
  left: 15px !important;
  z-index: 2 !important;

  color: #f0f0ed !important;
  font-size: 10px !important;
  letter-spacing: 0.8px !important;
}


/* =========================================================
   6. char 学生证布局
   ========================================================= */

.tc-header-main {
  position: static !important;
  z-index: 3 !important;
  display: block !important;
  min-height: 170px !important;
}

.tc-avatar-area {
  position: static !important;
  display: block !important;
}

.tc-avatar-frame {
  position: absolute !important;
  left: var(--id-avatar-left) !important;
  top: var(--id-avatar-top) !important;

  width: var(--id-avatar-w) !important;
  height: var(--id-avatar-h) !important;
  box-sizing: border-box !important;

  padding: 1px !important;
  background: #ffffff !important;
  border: 1px solid rgba(255,255,255,0.72) !important;
  border-radius: 5px !important;
  box-shadow:
    0 2px 5px rgba(0,0,0,0.10),
    inset 0 0 0 1px rgba(0,0,0,0.018) !important;
}

.tc-avatar-img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 3px !important;
  filter: contrast(0.98) saturate(0.92) !important;
}

.tc-avatar-overlay {
  display: none !important;
}


/* char 头像下方小名字 */
.tc-avatar-badge {
  position: absolute !important;
  left: var(--id-avatar-left) !important;
  top: calc(var(--id-avatar-top) + var(--id-avatar-h) + 6px) !important;

  width: var(--id-avatar-w) !important;
  max-width: var(--id-avatar-w) !important;
  padding: 0 !important;
  margin: 0 !important;

  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;

  color: #555 !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  line-height: 1.2 !important;
  text-align: center !important;
  text-transform: none !important;
}


/* char 右侧信息 */
.tc-meta-area {
  position: absolute !important;
  left: var(--id-info-left) !important;
  right: 28px !important;
  top: var(--id-avatar-top) !important;

  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  justify-content: flex-start !important;

  gap: 6px !important;
  min-width: 0 !important;
  padding-top: 0 !important;
}

.tc-meta-title {
  display: block !important;
  width: auto !important;

  padding-right: 170px !important;
  padding-bottom: 0 !important;

  border: none !important;
  background: transparent !important;
  box-shadow: none !important;

  color: #353535 !important;
  font-size: 22px !important;
  font-weight: 900 !important;
  line-height: 1.15 !important;
  letter-spacing: 0.2px !important;

  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

.tc-meta-subtitle {
  min-height: 14px !important;
  color: #777 !important;
  font-size: 12px !important;
  line-height: 1.25 !important;
  letter-spacing: 0.35px !important;
}

.tc-meta-subtitle::before {
  /* 【可改：char registered 文案】 */
  content: "registered moment profile" !important;

  color: #777 !important;
  font-style: italic !important;
}

.tc-meta-extra-1 {
  display: block !important;
  color: #777 !important;
  font-size: 12px !important;
  line-height: 1.25 !important;
  font-style: normal !important;
}

.tc-meta-extra-1::before {
  /* 【可改：char archive 文案】 */
  content: "Archive · Daily Record" !important;
}

.tc-meta-extra-2 {
  display: none !important;
}

.tc-meta-extra-2::before {
  content: "" !important;
}


/* char 的 page / words / date / time */
.tc-meta-stats {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center !important;
  gap: 10px !important;
  margin-top: -2px !important;
}

.tc-stat {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 4px !important;

  width: fit-content !important;
  padding: 0 !important;

  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;

  color: #555 !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  line-height: 1.2 !important;
  white-space: nowrap !important;
}

.tc-stat[data-label="page"],
.tc-stat[data-label="words"] {
  position: absolute !important;
  top: 2px !important;
  z-index: 6 !important;
  margin: 0 !important;
}

.tc-stat[data-label="page"] {
  right: 92px !important;
}

.tc-stat[data-label="words"] {
  right: 0 !important;
}

.tc-stat[data-label="date"],
.tc-stat[data-label="time"] {
  position: static !important;
}

.tc-stat[data-label="page"]::before {
  content: "NO." !important;
  color: #999 !important;
}

.tc-stat[data-label="words"]::before {
  content: "WORDS" !important;
  color: #999 !important;
}

.tc-stat[data-label="date"]::before {
  content: "DATE" !important;
  color: #999 !important;
}

.tc-stat[data-label="time"]::before {
  content: "TIME" !important;
  color: #999 !important;
}


/* =========================================================
   7. user 学生证布局
   user 没有 char 的完整 stats 结构，所以使用固定文案
   ========================================================= */

.tc-header-user .tc-avatar-frame-user {
  position: absolute !important;
  left: var(--id-avatar-left) !important;
  top: var(--id-avatar-top) !important;

  width: var(--id-avatar-w) !important;
  height: var(--id-avatar-h) !important;
  box-sizing: border-box !important;

  padding: 1px !important;
  background: #ffffff !important;
  border: 1px solid rgba(255,255,255,0.72) !important;
  border-radius: 5px !important;
  box-shadow:
    0 2px 5px rgba(0,0,0,0.10),
    inset 0 0 0 1px rgba(0,0,0,0.018) !important;

  overflow: visible !important;
}

.tc-header-user img,
.tc-header-user .tc-avatar-img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 3px !important;
  filter: contrast(0.98) saturate(0.92) !important;
}


/* user 主姓名 */
.tc-header-user .tc-avatar-badge-user {
  position: absolute !important;
  left: var(--id-info-left) !important;
  top: var(--id-avatar-top) !important;

  display: block !important;
  max-width: calc(100% - 205px) !important;

  margin: 0 !important;
  padding: 0 !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  color: #353535 !important;
  font-size: 22px !important;
  font-weight: 900 !important;
  line-height: 1.05 !important;
  letter-spacing: 0.1px !important;
  text-align: left !important;
  text-transform: none !important;

  white-space: nowrap !important;
  overflow: visible !important;
  text-overflow: clip !important;
}


/* user 只有 registered 这一行斜体 */
.tc-header-user .tc-avatar-badge-user::after {
  /* 【可改：user registered 文案】 */
  content: "registered moment profile" !important;

  display: block !important;

  /* 【可改：user 名字和 registered 的距离】数值越大距离越大 */
  margin-top: 3px !important;

  color: #777 !important;
  font-size: 11px !important;
  font-weight: 400 !important;
  font-style: italic !important;
  line-height: 1.14 !important;
  letter-spacing: 0.25px !important;
  text-transform: none !important;
}


/* user Archive 和自定义文案：不斜体 */
.tc-header-user .tc-avatar-frame-user::after {
  /*
    【可改：user archive 和自定义文案】
    \A 是换行。
    多写一个 \A\A 就是空一行。
  */
  content:
    "Archive · Daily Record\A\A"
    "天気良かったら行こう！" !important;

  position: absolute !important;

  /*
    【可改：user Archive/文案位置】
    left 越大越往右；top 越大越往下。
  */
  left: calc(var(--id-info-left) - var(--id-avatar-left)) !important;
  top: 48px !important;

  display: block !important;
  width: calc(var(--id-card-width) - 250px) !important;

  white-space: pre-line !important;

  color: #777 !important;
  font-size: 11px !important;
  font-weight: 400 !important;
  font-style: normal !important;
  line-height: 1.12 !important;
  letter-spacing: 0.2px !important;
  text-align: left !important;
}


/* =========================================================
   8. 删除分割线
   ========================================================= */

.tc-divider,
.tc-divider-text {
  display: none !important;
}


/* =========================================================
   9. 正文便签纸：无边框 + 只有正文滑动 + 渐隐
   ========================================================= */

.tm-body-char,
.tm-body-user {
  position: relative !important;

  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;

  flex: none !important;
  align-self: stretch !important;

  max-height: var(--id-body-max-height) !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  -webkit-overflow-scrolling: touch !important;

  background-color: rgba(255,255,255,0.58) !important;
  background-image:
    linear-gradient(rgba(224,224,220,0.92) 1px, transparent 1px) !important;
  background-size: 100% 1.65em !important;
  background-attachment: local !important;

  border: none !important;
  border-radius: 6px !important;

  padding: 9px 12px 9px 15px !important;

  color: var(--id-ink) !important;
  font-size: 14px !important;
  line-height: 1.68 !important;
  letter-spacing: 0.2px !important;

  box-shadow: none !important;

  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    black 7%,
    black 93%,
    transparent 100%
  ) !important;
  mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    black 7%,
    black 93%,
    transparent 100%
  ) !important;

  -webkit-mask-size: 100% 100% !important;
  mask-size: 100% 100% !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
}

.tm-body-char::-webkit-scrollbar,
.tm-body-user::-webkit-scrollbar {
  width: 4px !important;
}

.tm-body-char::-webkit-scrollbar-track,
.tm-body-user::-webkit-scrollbar-track {
  background: transparent !important;
  margin: 6px 0 !important;
}

.tm-body-char::-webkit-scrollbar-thumb,
.tm-body-user::-webkit-scrollbar-thumb {
  background: var(--id-scroll-thumb) !important;
  border-radius: 999px !important;
}

.tm-body-char::-webkit-scrollbar-thumb:hover,
.tm-body-user::-webkit-scrollbar-thumb:hover {
  background: var(--id-scroll-thumb-hover) !important;
}

.tm-para-block {
  margin: 0 0 0.85em 0 !important;
}

.tm-para-block:last-child {
  margin-bottom: 0 !important;
}


/* =========================================================
   10. 文字格式
   ========================================================= */

.tm-bold {
  color: #222 !important;
  font-weight: 900 !important;
  background: linear-gradient(transparent 58%, rgba(205,205,200,0.6) 58%) !important;
  padding: 0 2px !important;
}

.tm-action {
  color: #666 !important;
  font-style: italic !important;
}

.tm-del {
  color: #999 !important;
  text-decoration-thickness: 1px !important;
}

.tm-quote-block {
  position: relative !important;
  margin: 8px 0 !important;
  padding: 8px 11px 8px 14px !important;

  background: rgba(246,246,243,0.88) !important;
  border-left: 3px solid #a8a8a3 !important;
  border-radius: 5px !important;

  color: #3c3c3c !important;
}


/* =========================================================
   11. 语音 / 翻译
   ========================================================= */

.tm-voice-controls {
  margin-top: 10px !important;
}

.tm-voice-btn {
  background: rgba(255,255,255,0.82) !important;
  border: 1px solid #d0d0cc !important;
  border-radius: 999px !important;
  color: #666 !important;
}

.tm-voice-btn svg {
  color: #666 !important;
  stroke: #666 !important;
}

.tm-translation-section {
  margin-top: 10px !important;
  background: rgba(255,255,255,0.58) !important;
  border: 1px dashed #cfcfcb !important;
  border-radius: 7px !important;
  overflow: hidden !important;
}

.tm-translation-toggle {
  padding: 7px 10px !important;
  background: rgba(245,245,242,0.82) !important;
  color: #666 !important;
  font-size: 12px !important;
}

.tm-translation-body {
  padding: 10px 12px !important;
  color: #555 !important;
  font-size: 13px !important;
  line-height: 1.55 !important;
}


/* =========================================================
   12. 输入区
   ========================================================= */

.tm-compose {
  background: rgba(250,250,247,0.82) !important;
  border-top: 1px solid rgba(185,185,180,0.55) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  box-shadow: 0 -6px 22px rgba(0,0,0,0.05) !important;
}

.tm-compose-toolbar {
  gap: 7px !important;
}

.tm-regen-btn,
.tm-suggestions-btn {
  background: rgba(255,255,255,0.82) !important;
  border: 1px solid #cececa !important;
  border-radius: 999px !important;
  color: #666 !important;
}

.tm-regen-btn svg,
.tm-suggestions-btn svg {
  color: #666 !important;
  stroke: #666 !important;
}

.tm-regen-btn.active,
.tm-suggestions-btn.active {
