}

.tm-compose-row {
  gap: 8px !important;
}

.tm-input {
  background: #ffffff !important;
  border: 1px solid #d4d4d0 !important;
  border-radius: 10px !important;

  color: #333 !important;
  line-height: 1.5 !important;

  box-shadow:
