}

.tm-context-menu button {
  color: #444 !important;
}

.tm-ctx-delete {
  color: #a55 !important;
}


/* =========================================================
   15. 手机窄屏适配
   ========================================================= */

@media (max-width: 520px) {
  :root {
    --id-card-width: 90vw;
    --id-body-max-height: 420px;

    /* 【可改：手机端头像大小】 */
    --id-avatar-w: 96px;
    --id-avatar-h: 124px;

    /* 【可改：手机端头像位置】 */
    --id-avatar-left: 18px;
    --id-avatar-top: 80px;

    /* 【可改：手机端右侧信息位置】 */
    --id-info-left: 130px;

    --id-header-height: 242px;
  }

  .tm-story {
    padding: 14px 12px 50px 12px !important;
  }

  .tm-para {
    margin: 2px auto !important;
  }

  .tm-para-char,
  .tm-para-user {
    width: var(--id-card-width) !important;
    max-width: var(--id-card-width) !important;
    margin-left: auto !important;
    margin-right: auto !important;
    padding: 9px 12px 9px 12px !important;
  }

  .tc-header,
  .tc-header-user {
    min-height: var(--id-header-height) !important;
    padding: 68px 12px 10px 12px !important;
    margin-bottom: 6px !important;
  }

  .tc-header::before,
  .tc-header-user::before {
    font-size: 15px !important;
    letter-spacing: 0.7px !important;
  }

  .tc-avatar-frame,
  .tc-header-user .tc-avatar-frame-user {
    left: var(--id-avatar-left) !important;
    top: var(--id-avatar-top) !important;
    width: var(--id-avatar-w) !important;
    height: var(--id-avatar-h) !important;
    padding: 1px !important;
  }

  .tc-avatar-badge {
    left: var(--id-avatar-left) !important;
    top: calc(var(--id-avatar-top) + var(--id-avatar-h) + 5px) !important;
    width: var(--id-avatar-w) !important;
    max-width: var(--id-avatar-w) !important;
    font-size: 10px !important;
  }

