  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, #8b7cf0, rgba(139,124,240,0.2));
  border-radius: 12px 12px 0 0;
}
.xt-text-game::after {
  content: "";
  position: absolute;
  left: 16px; right: 16px; bottom: 10px;
  height: 5px;
  border-radius: 3px;
  background: linear-gradient(90deg, #8b7cf0 0 70%, rgba(255,255,255,0.08) 70% 100%);
}
.xt-text-album_1,
.xt-text-album_2,
.xt-text-album_3 {
  position: relative;
  padding: 14px 16px;
  background: linear-gradient(160deg, #1c1c20, #131316);
