  font-weight: 700;
}
.xt-text-delivery {
  position: relative;
  padding: 12px 14px;
  background: linear-gradient(135deg, #2a1a10, #1a1510);
  border: 1px solid rgba(255,102,0,0.25);
  border-left: 3px solid #ff6600;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2;
  color: #f5f5f3;
}
.xt-text-delivery::first-line {
  color: #ff6600;
  font-weight: 700;
}
.xt-text-delivery::after {
  content: "";
  display: block;
  height: 4px;
  border-radius: 2px;
  margin-top: 10px;
  background: linear-gradient(90deg, #ff6600 0 65%, rgba(255,255,255,0.1) 65% 100%);
}
/* ===== 第10段 · 钱包/账单/健康/日程/闹钟 ===== */
.xt-text-wallet_app {
  position: relative;
  padding: 46px 18px 16px;
  border-radius: 16px;
  background: linear-gradient(135deg, #0e3a66, #1677ff);
  border: 1px solid rgba(22,119,255,0.5);
  box-shadow: 0 8px 24px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.15);
  font-size: 14px; line-height: 2;
  color: #f5f7fa; letter-spacing: 0.3px;
