}
.xt-text-bills_income {
  padding: 12px 14px;
  background: #0d2b1e;
  border: 1px solid rgba(34,197,94,0.3);
  border-radius: 12px;
  font-size: 13px; line-height: 2;
  color: rgba(255,255,255,0.9);
}
.xt-text-bills_income::before {
  content: "收入";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #4ade80;
  margin-bottom: 6px;
}
.xt-row { display: flex; gap: 10px; }
.xt-row > * { flex: 1; }
.xt-ring { margin-bottom: 6px; }
.xt-ring-fill { stroke: #c9a86a; }
.xt-ring-value { color: #f5f5f3; font-weight: 700; }
.xt-ring-label { color: rgba(245,245,243,0.6); }
.xt-text-health_steps {
  padding: 10px 14px;
  background: #10231a;
  border: 1px solid rgba(34,197,94,0.2);
  border-left: 3px solid #22c55e;
  border-radius: 12px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin-top: 10px;
}
.xt-text-health_sleep {
  padding: 10px 14px;
  background: #10231a;
  border: 1px solid rgba(34,197,94,0.2);
  border-left: 3px solid #22c55e;
  border-radius: 12px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin-top: 8px;
}
/* 日程与待办：行距加大，一条一行 */
.xt-text-calendar_note {
  padding: 10px 14px 10px 16px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.3;
  color: rgba(245,245,243,0.75);
}
.xt-text-alarm {
  padding: 12px 14px;
  background: #211d16;
  border: 1px solid rgba(201,168,106,0.18);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: #f5f5f3;
}
/* ===== 第11段 · 微信 ===== */
.xt-text-chat_a_title,
.xt-text-chat_b_title,
.xt-text-chat_g_title {
  text-align: center;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #f5f5f3;
  padding: 4px 0 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid rgba(7,193,96,0.35);
}
.xt-bubble,
.xt-bubble-left,
.xt-bubble-right,
.xt-bubble-body {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.xt-bubbles {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.xt-bubble-left {
  align-self: flex-start;
  max-width: 82%;
  background: #2a2a30 !important;
  border-radius: 12px 12px 12px 4px !important;
  padding: 7px 11px;
  font-size: 12.5px; line-height: 1.65;
  color: #f5f5f3 !important;
}
.xt-bubble-right {
  align-self: flex-end;
  max-width: 82%;
  background: linear-gradient(135deg, #07c160, #06a04f) !important;
  border-radius: 12px 12px 4px 12px !important;
  padding: 7px 11px;
  font-size: 12.5px; line-height: 1.65;
  color: #ffffff !important;
}
/* ===== 第12段 · 通话/收藏/好友 ===== */
.xt-text-call {
  position: relative;
  padding: 10px 12px 10px 14px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 12px; line-height: 1.9;
  color: rgba(245,245,243,0.8);
}
.xt-text-call::first-line {
  color: #c9a86a;
  font-weight: 700;
}
.xt-text-call::after {
  content: "";
  position: absolute;
  right: 12px; top: 14px;
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #e74c3c;
  box-shadow: 0 0 4px rgba(231,76,60,0.5);
}
.xt-text-fav {
  position: relative;
  padding: 10px 14px 10px 34px;
  background: #211f1b;
  border: 1px solid rgba(201,168,106,0.15);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2;
  color: rgba(245,245,243,0.8);
}
.xt-text-fav::before {
  content: "★";
  position: absolute;
  left: 13px; top: 50%;
  transform: translateY(-50%);
  color: #e6b46a;
  font-size: 15px;
}
.xt-text-p1avt, .xt-text-p2avt {
  display: inline-block;
  width: 40px; height: 40px;
